20	// The bundled functional engine. QEMU does not implement --describe, so its
21	// descriptor is built in. Binary path honors $VSIM_QEMU (matching hsim) then
22	// the default build location. Exposed (engine_registry.hpp) so `run --model
23	// fast` resolves qemu directly, skipping the directory scan + per-engine
24	// --describe subprocesses that whole-registry discovery would spawn.
25	EngineDescriptor builtin_qemu() {
26	  EngineDescriptor d;
27	  d.id = "qemu";
28	  d.type = "qemu";
29	  d.kind = "functional";
30	  d.xlen = 64;
31	  d.triggers = {"csr", "pc", "icount", "simpoint"};
32	  d.roles = {"standalone", "fast-leg"};
33	  d.state = {"drain"};
34	  d.source = "built-in";
35	  // The hybrid fast-forward leg: load the ELF, drain on the plugin's trigger
36	  // into {state_out}, exit 200. Mirrors orchestrator/spawn.py::qemu_drain_argv
37	  // and tests/e2e.sh's QEMU-1 launch. {plugin}/{mmap}/{mmap_size}/{state_out}
38	  // are filled by the plan executor (F6).
39	  d.invoke.push_back(
40	      {"fast-leg",
41	       {"{bin}", "-object",
42	        "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
43	        "-machine", "andes_ae350,memory-backend=mem", "-cpu",
44	        "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
45	        "enable=on,target=native", "-bios", "{elf}", "-plugin",
46	        "{plugin},outfile={state_out}"}});
47	  // The standalone functional run (model=fast): the same andes machine as the
48	  // fast-leg, minus the hybrid sharing/plugin bits. run_passthrough fills
49	  // {bin}/{elf}; the user's post-`--` args (gdbstub, monitor, ...) append after.
50	  d.invoke.push_back(
51	      {"standalone",
52	       {"{bin}", "-machine", "andes_ae350", "-cpu", "andes-ax45mpv,vlen=512",
53	        "-nographic", "-semihosting-config", "enable=on,target=native", "-bios",
54	        "{elf}"}});
55	  if (const char* q = std::getenv("VSIM_QEMU"); q && *q)
56	    d.bin_path = q;
57	  else
58	    d.bin_path = (repo_root() / "build" / "qemu" / "qemu-system-riscv64").string();
59	  return d;
60	}
