79	// Ask one binary to describe itself: try `<bin> --describe`, else read the
80	// <bin>.json sidecar. On success fills `d` and returns true; on failure leaves
81	// a human-readable note in `warn`.
82	bool describe_one(const fs::path& bin, EngineDescriptor& d, std::string& warn) {
83	  RunResult r = run_process({bin.string(), "--describe"}, kDescribeTimeoutMs);
84	  if (!r.spawn_failed && !r.timed_out && r.rc == 0) {
85	    json::Parsed p = json::parse(r.out);
86	    if (p.ok) {
87	      std::string err = descriptor_from_json(p.value, d);
88	      if (err.empty()) {
89	        d.bin_path = bin.string();
90	        d.source = "--describe";
91	        return true;
92	      }
93	      warn = bin.string() + ": --describe JSON invalid: " + err;
94	    } else {
95	      warn = bin.string() + ": --describe output is not JSON: " + p.error;
96	    }
97	  }
98	
99	  fs::path sidecar = bin;
100	  sidecar += ".json";
101	  std::error_code ec;
102	  if (fs::exists(sidecar, ec)) {
103	    json::Parsed p = json::parse(read_file(sidecar));
104	    if (p.ok) {
105	      EngineDescriptor sd;
106	      std::string err = descriptor_from_json(p.value, sd);
107	      if (err.empty()) {
108	        sd.bin_path = bin.string();
109	        sd.source = "sidecar";
110	        d = std::move(sd);
111	        return true;
112	      }
113	      warn = sidecar.string() + ": invalid descriptor: " + err;
114	    } else {
115	      warn = sidecar.string() + ": not JSON: " + p.error;
116	    }
117	  }
118	
119	  if (warn.empty()) warn = bin.string() + ": no --describe and no sidecar";
120	  return false;
121	}
