151	Discovery discover_engines() {
152	  Discovery out;
153	  std::set<std::string> seen;
154	
155	  EngineDescriptor qemu = builtin_qemu();
156	  seen.insert(qemu.id);
157	  out.engines.push_back(std::move(qemu));
158	
159	  if (const char* env = std::getenv("ANDES_SIM_ENGINES_DIR"); env && *env) {
160	    std::stringstream ss(env);
161	    std::string dir;
162	    while (std::getline(ss, dir, ':'))
163	      if (!dir.empty()) scan_dir(dir, /*prefix=*/"", out, seen);
164	  } else {
165	    scan_dir(repo_root() / "verilator" / "build", /*prefix=*/"sim_", out, seen);
166	  }
167	  return out;
168	}
