62	// `run --model accurate`: one cycle-accurate engine alone, from reset (no QEMU,
63	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
64	// engine's own output. Unlike fast, this must discover the Verilator build(s)
65	// to resolve the engine (explicit --engine, else the sole one).
66	int run_accurate(const Cli& cli) {
67	  Discovery disc = discover_engines();
68	  std::string err;
69	  const EngineDescriptor* eng =
70	      resolve_accurate_engine(disc.engines, cli.engine, err);
71	  if (!eng) {
72	    std::fprintf(stderr, "andes-sim run --model accurate: %s\n", err.c_str());
73	    // Surface why an expected engine may be absent (failed --describe, etc.).
74	    for (const std::string& w : disc.warnings)
75	      std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
76	    return 2;
77	  }
78	  return run_standalone(cli, *eng, "accurate");
79	}
